function save(config){if(!cur?.host||hostPlayer(cur.room.peers())?.presence.go)return;const b=KartBots.normalize(config,cur.room.peers().length);SAVE.mpBotCount=b.count;SAVE.mpBotItems=b.items;SAVE.mpBotCars=[...b.cars];SAVE.mpBotDifficulties=[...b.difficulties];persist();cur.room.presence({bots:b}).catch(()=>{})}
